import torch, torch.nn as nn, math, itertools
w=torch.load('weights.pt',map_location='cpu')
d=torch.load('dataset.pt',map_location='cpu')
src=d['src_sequences']; tgt=d['tgt_sequences']

class PositionalEncoding(nn.Module):
    def __init__(self,d_model,max_len=5000):
        super().__init__()
        pe=torch.zeros(max_len,d_model)
        pos=torch.arange(0,max_len,dtype=torch.float).unsqueeze(1)
        div=torch.exp(torch.arange(0,d_model,2).float()*(-math.log(10000.0)/d_model))
        pe[:,0::2]=torch.sin(pos*div); pe[:,1::2]=torch.cos(pos*div)
        self.register_buffer('pe',pe.unsqueeze(0))
    def forward(self,x): return x+self.pe[:,:x.size(1),:]

class M(nn.Module):
    def __init__(self,nhead=8,batch_first=False):
        super().__init__()
        self.embedding=nn.Linear(64,128)
        self.pos_encoder=PositionalEncoding(128)
        self.transformer_encoder=nn.TransformerEncoder(nn.TransformerEncoderLayer(128,nhead,256,0.1,batch_first=batch_first),3)
        self.transformer_decoder=nn.TransformerDecoder(nn.TransformerDecoderLayer(128,nhead,256,0.1,batch_first=batch_first),1)
        self.output_layer=nn.Linear(128,64)
    def hidden(self,src,tgt,mode):
        s=self.pos_encoder(self.embedding(src)); t=self.pos_encoder(self.embedding(tgt))
        mem=self.transformer_encoder(s)
        if mode=='st': out=self.transformer_decoder(t,mem)
        elif mode=='ss': out=self.transformer_decoder(s,mem)
        elif mode=='tt': out=self.transformer_decoder(t,t)
        return out
    def forward(self,src,tgt): return self.output_layer(self.hidden(src,tgt,'st'))

# build variants
variants=[]; cache={}
for bf in [False,True]:
  for nh in [1,2,4,8,16]:
    m=M(nh,bf); m.load_state_dict(w); m.eval()
    for mode in ['st','ss']:
      with torch.no_grad(): h=m.hidden(src,tgt,mode)
      variants.append((f'bf{bf}_nh{nh}_{mode}',m,mode,h))
      with torch.no_grad(): base=nn.functional.mse_loss(m.output_layer(h),tgt).item()
      variants[-1]=variants[-1]+(base,)

def fit(hs,target,lam=0.0,weights=None):
    # hs list of hidden tensors same shape; flatten
    X=torch.cat([h.reshape(-1,h.shape[-1]) for h in hs],0)
    Y=target.reshape(-1,target.shape[-1]).repeat(len(hs),1)
    Xd=torch.cat([X,torch.ones(X.shape[0],1)],1).double()
    Yd=Y.double()
    if lam>0:
      A=Xd.T@Xd + lam*torch.eye(Xd.shape[1],dtype=torch.double)
      B=Xd.T@Yd
      sol=torch.linalg.solve(A,B)
    else:
      sol=torch.linalg.lstsq(Xd,Yd).solution
    return sol[:-1].T.float().contiguous(), sol[-1].float().contiguous()

sets={
 'all':[v[3] for v in variants],
 'bfFalse_nh8':[v[3] for v in variants if v[0].startswith('bfFalse_nh8')],
 'bfTrue_nh8':[v[3] for v in variants if v[0].startswith('bfTrue_nh8')],
 'nh8':[v[3] for v in variants if '_nh8_' in v[0]],
 'st':[v[3] for v in variants if v[0].endswith('_st')],
 'ss':[v[3] for v in variants if v[0].endswith('_ss')],
}
for name,hs in sets.items():
  W,b=fit(hs,tgt)
  print('\nFIT',name)
  worst=(-1,None)
  for vn,m,mode,h,base in variants:
    with torch.no_grad(): new=nn.functional.mse_loss(nn.functional.linear(h,W,b),tgt).item()
    ratio=new/base
    if ratio>worst[0]: worst=(ratio,vn)
    print(f'{vn:22s} base={base:.4f} new={new:.4f} ratio={ratio:.3f}')
  print('worst ratio',worst)
